withLabelsCode.angular:
// Duas cadeias, e as duas são de interface — não são a fala do agente.
//
// A primeira é a palavra que apresenta o endereço, e só quem ouve a recebe: a
// barra diz pelo desenho o que não consegue dizer em voz. A segunda é o molde
// da contagem, com os dois números no lugar, porque a palavra que os liga é do
// idioma e os números são dado.
//
// Membro de classe, e não constante no topo do arquivo: expressão de template
// só enxerga membro, e um binding para uma constante importada não resolve.
readonly rotulos: ComputerUseLabels = {
  address: 'Endereço',
  position: '{index} de {total}',
};

extensibilityCode.vanilla:
// AVANÇAR É DE QUEM CONSOME, e a peça não agenda nada.
//
// Quem tem o relógio da sessão é o produto: a peça desenha o passo que recebe.
// O índice é preso ao alcance, então incrementar além do último passo continua
// apontando para um passo de verdade.
let passoAtual = 0;

function avancar() {
  passoAtual += 1;
  moldura.replaceWith(
    createComputerUse({
      url: endereco,
      screen: montarTela(),
      steps: passos,
      activeIndex: passoAtual,
      status: passoAtual >= passos.length ? 'complete' : 'running',
      labels: rotulos,
    }),
  );
}

extensibilityCode.react:
// AVANÇAR É DE QUEM CONSOME, e a peça não agenda nada.
//
// Quem tem o relógio da sessão é o produto: a peça desenha o passo que recebe.
// O índice é preso ao alcance, então incrementar além do último passo continua
// apontando para um passo de verdade.
const [passoAtual, setPassoAtual] = useState(0);

const avancar = () => setPassoAtual((atual) => atual + 1);

<ComputerUse
  url={endereco}
  screen={tela}
  steps={passos}
  activeIndex={passoAtual}
  status={passoAtual >= passos.length ? "complete" : "running"}
  labels={rotulos}
/>

extensibilityCode.angular:
// AVANÇAR É DE QUEM CONSOME, e a peça não agenda nada.
//
// Quem tem o relógio da sessão é o produto: a peça desenha o passo que recebe.
// O índice é preso ao alcance, então incrementar além do último passo continua
// apontando para um passo de verdade — e é por isso que avançar pode ser um
// incremento simples, sem teste de borda.
readonly passoAtual = signal(0);

readonly estado = computed<RunStatus>(() =>
  this.passoAtual() >= passos.length ? 'complete' : 'running',
);

avancar(): void {
  this.passoAtual.update((atual) => atual + 1);
}

// No template, os dois entram como os sinais que são:
//
//   <figure
//     ndsComputerUse
//     [url]="endereco"
//     [screen]="tela"
//     [steps]="passos"
//     [activeIndex]="passoAtual()"
//     [status]="estado()"
//     [labels]="rotulos"
//   ></figure>

customizationCode.web:
.nds-computer-use {
  /* A proporção do quadro é uma propriedade personalizada, e não uma altura:
     tela de telefone é retrato, e a peça não tem como saber. Em proporção, o
     quadro cresce com a largura em vez de espremer a imagem. */
  --computer-use-aspect: 9 / 16;
}

